api_surface_examples:
TypeScript example:
import { RedwoodClient } from '@redwood/inference'
const c = new RedwoodClient()
const adapter = c.adapters.compact({ mode: 'fetch', pageSize: 100, maxPrefetchPages: 2 })
for await (const rec of adapter.iterate('responses.list')) {
  handle(rec)
}

Go example:
client := redwood.NewClient(nil)
ad := client.Adapters().Compact(redwood.AdapterOpts{Mode: redwood.ModeStream, PageSize: 25, ResumeWindowSeconds: 20})
ctx := context.Background()
it := ad.Iterate(ctx, "responses.stream")
for it.Next() {
  item := it.Value()
  handle(item)
}
if err := it.Err(); err != nil {
  log.Printf("adapter iteration error: %v", err)
}
